/* Dr. Cotterell's style changes.
 * They're all marked as important because that's what got them to apply.
 */
div.ExecutionVisualizer {
  padding: 0 !important;
  font-family: "Recursive", monospace !important;
  font-variation-settings: "MONO" 1 !important;
  font-optical-sizing: auto !important;
  font-smooth: auto !important;
  -webkit-font-smoothing: auto !important;
}

.isFinal .stackFrameValue,
.isFinal .instVal {
  filter: brightness(85%);
}

:root {
  --object-background-color: #faebbf;
  --object-border: 1px solid black;
  --object-border-radius: 0.2rem;
  --value-background-color: #ffffc6;
  --value-border: var(--object-border);
  --value-border-radius: var(--object-border-radius);
}

div.ExecutionVisualizer,
div.ExecutionVisualizer * {
  font-family: "Recursive", monospace !important;
  font-variation-settings: "MONO" 1 !important;
  font-optical-sizing: auto !important;
  font-smooth: auto !important;
  -webkit-font-smoothing: auto !important;
}

div.ExecutionVisualizer .stackFrame {
  border-left: 1px solid #a6b3b6 !important;
  border-right: 1px solid #a6b3b6 !important;
}

div.ExecutionVisualizer .stackFrameHeader {
  font-size: small !important;
}

div.ExecutionVisualizer .instTbl,
div.ExecutionVisualizer .listTbl {
  border: var(--object-border) !important;
  border-radius: var(--object-border-radius) !important;
  background-color: var(--object-background-color) !important;
  border-spacing: unset !important;
}

div.ExecutionVisualizer .stackFrameVarTable {
  background-color: revert !important;
}

div.ExecutionVisualizer .instKey,
div.ExecutionVisualizer .stackFrameVar {
  font-size: small !important;
  border: transparent !important;
  padding: 1px !important;
  padding-left: 6px !important;
  padding-right: 6px !important;
}

div.ExecutionVisualizer .javaStackVarThis {
  color: #de4b58;
}

div.ExecutionVisualizer .instVal,
div.ExecutionVisualizer .listElt,
div.ExecutionVisualizer .stackFrameValue {
  border: var(--value-border) !important;
  border-radius: var(--value-border-radius) !important;
  background-color: var(--value-background-color) !important;
  padding: 1px !important;
  padding-left: 6px !important;
  padding-right: 6px !important;
  font-size: x-small !important;
  min-width: 1.25rem !important;
}

div.ExecutionVisualizer .listHeader {
  font-size: xx-small !important;
  border: transparent !important;
}

div.ExecutionVisualizer .listTbl.array-vertical > tr > .listHeader,
div.ExecutionVisualizer .listTbl.array-vertical > tbody > tr > .listHeader {
  text-align: right;
  vertical-align: middle;
  padding: 2px 6px;
}

div.ExecutionVisualizer .nullObj {
  font-size: x-small !important;
}

div.ExecutionVisualizer .instTbl:not(:has(.instKey)):not(.emptyInst) {
  background-color: var(--value-background-color) !important;
}

div.ExecutionVisualizer .instTbl.emptyInst,
div.ExecutionVisualizer .listTbl.emptyList {
  display: inline-block;
  min-width: 2.5rem;
  height: 1.5rem;
  background-color: var(--object-background-color) !important;
}

div.ExecutionVisualizer .instTbl.emptyStringTbl {
  min-width: 2.5rem !important;
}

div.ExecutionVisualizer .instVal.emptyStringVal {
  white-space: nowrap !important;
  text-align: center !important;
  padding: 3px 8px !important;
  box-sizing: border-box;
}

div.ExecutionVisualizer .colorObjTbl {
  border: var(--object-border) !important;
  border-radius: var(--object-border-radius) !important;
  background-color: var(--value-background-color) !important;
  border-spacing: unset !important;
}

div.ExecutionVisualizer .colorObjElt {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  padding: 3px 6px !important;
}

div.ExecutionVisualizer .colorSwatchContainer {
  display: inline-block;
  width: 16px !important;
  height: 16px !important;
  border-radius: 3px !important;
  background-image: repeating-linear-gradient(45deg, #ccc 25%, transparent 25%),
    repeating-linear-gradient(-45deg, #ccc 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #ccc 75%),
    linear-gradient(-45deg, transparent 75%, #ccc 75%) !important;
  background-size: 8px 8px !important;
  background-position: 0 0, 0 4px, 4px -4px, -4px 0px !important;
  background-color: #fff !important;
  border: 1px solid rgba(0, 0, 0, 0.3) !important;
  overflow: hidden !important;
  flex-shrink: 0 !important;
  vertical-align: middle !important;
}

div.ExecutionVisualizer .colorSwatch {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
}

div.ExecutionVisualizer .colorHexLabel {
  font-family: "Recursive", monospace !important;
  font-size: x-small !important;
  color: #222 !important;
  font-weight: 600 !important;
  letter-spacing: 0.5px !important;
}
/* /Dr. Cotterell's style changes */

div.ExecutionVisualizer .fieldTypeLabel {
    font-size: 8pt!important;
}

div.ExecutionVisualizer table {
    border-collapse: separate;
}

div.ExecutionVisualizer div#heap {
    padding-left: unset!important;
}
